// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by time.Now.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// It refills tokens at rate tokens per second, up to capacity.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

var (
	ErrNonPositiveCapacity = errors.New("ratelimit: capacity must be > 0")
	ErrNonPositiveRate     = errors.New("ratelimit: rate must be > 0")
	ErrNilClock            = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given burst capacity (tokens), refill
// rate (tokens per second), and clock. If clock is nil, RealClock is used.
func New(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrNonPositiveCapacity
	}
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	return &Limiter{
		tokens:   float64(capacity),
		capacity: float64(capacity),
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// Tokens accrue continuously at the configured rate, capped at capacity.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (approximate
// under concurrency; primarily for tests and observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
