// ratelimit_test.go
package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu   sync.Mutex
	now  time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{now: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewValidation(t *testing.T) {
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  error
	}{
		{"ok", 10, 1.0, newFakeClock(), nil},
		{"nil clock uses real", 10, 1.0, nil, nil},
		{"zero capacity", 0, 1.0, newFakeClock(), ErrNonPositiveCapacity},
		{"negative capacity", -1, 1.0, newFakeClock(), ErrNonPositiveCapacity},
		{"zero rate", 10, 0, newFakeClock(), ErrNonPositiveRate},
		{"negative rate", 10, -0.5, newFakeClock(), ErrNonPositiveRate},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, err := New(tc.capacity, tc.rate, tc.clock)
			if tc.wantErr != nil {
				if err != tc.wantErr {
					t.Fatalf("New() err = %v, want %v", err, tc.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("New() unexpected err: %v", err)
			}
			if l == nil {
				t.Fatal("New() returned nil limiter")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	tests := []struct {
		name       string
		capacity   int
		rate       float64
		steps      []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name: "burst up to capacity then denied",
			capacity: 3, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true}, {0, 1, true}, {0, 1, true}, {0, 1, false},
			},
		},
		{
			name: "refill over time",
			capacity: 2, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true}, {0, 1, false},
				{time.Second, 1, true}, {0, 1, false},
				{500 * time.Millisecond, 1, false},
				{500 * time.Millisecond, 1, true},
			},
		},
		{
			name: "tokens capped at capacity",
			capacity: 2, rate: 10,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{time.Hour, 2, true},
				{0, 1, false},
			},
		},
		{
			name: "request larger than capacity always denied",
			capacity: 2, rate: 5,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 3, false},
				{time.Hour, 3, false},
			},
		},
		{
			name: "zero request allowed if capacity positive",
			capacity: 1, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 0, true}, {0, 0, true},
			},
		},
		{
			name: "negative request denied",
			capacity: 1, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, -1, false},
			},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			clk := newFakeClock()
			l, err := New(tc.capacity, tc.rate, clk)
			if err != nil {
				t.Fatalf("New() err: %v", err)
			}
			for i, s := range tc.steps {
				clk.Advance(s.advance)
				if got := l.AllowN(s.n); got != s.want {
					t.Errorf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllowAndTokens(t *testing.T) {
	clk := newFakeClock()
	l, _ := New(5, 2, clk)
	if !l.Allow() {
		t.Fatal("Allow() = false, want true")
	}
	if got := l.Tokens(); got != 4 {
		t.Errorf("Tokens() = %v, want 4", got)
	}
	clk.Advance(2 * time.Second)
	if got := l.Tokens(); got != 6 {
		t.Errorf("Tokens() after refill = %v, want 6 (capped at 5 on next use)", got)
	}
}

func TestConcurrentAccess(t *testing.T) {
	clk := newFakeClock()
	l, _ := New(100, 1000, clk)
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 10; j++ {
				if l.AllowN(1) {
					mu.Lock()
					allowed++
					mu.Unlock()
				}
			}
		}()
	}
	wg.Wait()
	if allowed > 100 {
		t.Errorf("allowed = %d, want <= 100", allowed)
	}
}
